CREATE TABLE IF NOT EXISTS inventory_category (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY inventory_category_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_item (id CHAR(36) PRIMARY KEY, code VARCHAR(30) NOT NULL, name VARCHAR(200) NOT NULL, category_id CHAR(36) NOT NULL, issue_unit VARCHAR(30) NOT NULL, purchase_unit VARCHAR(30) NOT NULL, purchase_unit_factor INT NOT NULL, reorder_point INT NOT NULL DEFAULT 0, tracks_expiry TINYINT(1) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY inventory_item_code_unique (code), KEY inventory_item_category (category_id), CONSTRAINT inventory_item_category_fk FOREIGN KEY (category_id) REFERENCES inventory_category(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_item_barcode (id CHAR(36) PRIMARY KEY, item_id CHAR(36) NOT NULL, barcode VARCHAR(64) NOT NULL, unit_kind VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY inventory_item_barcode_unique (barcode), KEY inventory_item_barcode_item (item_id), CONSTRAINT inventory_item_barcode_item_fk FOREIGN KEY (item_id) REFERENCES inventory_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_vendor (id CHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', address VARCHAR(500) NOT NULL DEFAULT '', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY inventory_vendor_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_receipt (id CHAR(36) PRIMARY KEY, reference VARCHAR(32) NOT NULL, kind VARCHAR(16) NOT NULL, vendor_id CHAR(36) NULL, document_no VARCHAR(60) NULL, received_on DATE NOT NULL, status VARCHAR(16) NOT NULL, created_by_person_id CHAR(36) NOT NULL, posted_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY inventory_receipt_reference_unique (reference), KEY inventory_receipt_kind_time (kind, created_at), CONSTRAINT inventory_receipt_vendor_fk FOREIGN KEY (vendor_id) REFERENCES inventory_vendor(id), CONSTRAINT inventory_receipt_creator_fk FOREIGN KEY (created_by_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_receipt_line (id CHAR(36) PRIMARY KEY, receipt_id CHAR(36) NOT NULL, line_no INT NOT NULL, item_id CHAR(36) NOT NULL, entered_unit_kind VARCHAR(16) NOT NULL, entered_quantity INT NOT NULL, entered_unit_price DECIMAL(14,2) NOT NULL, unit_factor INT NOT NULL, issue_quantity INT NOT NULL, unit_cost DECIMAL(14,4) NOT NULL, line_total DECIMAL(16,2) NOT NULL, manufacturer_lot_no VARCHAR(60) NULL, expiry_date DATE NULL, KEY inventory_receipt_line_receipt (receipt_id, line_no), CONSTRAINT inventory_receipt_line_receipt_fk FOREIGN KEY (receipt_id) REFERENCES inventory_receipt(id), CONSTRAINT inventory_receipt_line_item_fk FOREIGN KEY (item_id) REFERENCES inventory_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_lot (id CHAR(36) PRIMARY KEY, lot_code VARCHAR(32) NOT NULL, item_id CHAR(36) NOT NULL, receipt_line_id CHAR(36) NOT NULL, manufacturer_lot_no VARCHAR(60) NULL, expiry_date DATE NULL, unit_cost DECIMAL(14,4) NOT NULL, received_quantity INT NOT NULL, on_hand_quantity INT NOT NULL, received_at DATETIME NOT NULL, UNIQUE KEY inventory_lot_code_unique (lot_code), KEY inventory_lot_item (item_id, on_hand_quantity), KEY inventory_lot_receipt_line (receipt_line_id), CONSTRAINT inventory_lot_on_hand_nonnegative CHECK (on_hand_quantity >= 0), CONSTRAINT inventory_lot_item_fk FOREIGN KEY (item_id) REFERENCES inventory_item(id), CONSTRAINT inventory_lot_receipt_line_fk FOREIGN KEY (receipt_line_id) REFERENCES inventory_receipt_line(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_movement (id CHAR(36) PRIMARY KEY, lot_id CHAR(36) NOT NULL, item_id CHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, quantity INT NOT NULL, unit_cost DECIMAL(14,4) NOT NULL, source_type VARCHAR(32) NOT NULL, source_id CHAR(36) NOT NULL, actor_person_id CHAR(36) NOT NULL, occurred_at DATETIME(6) NOT NULL, KEY inventory_movement_item_time (item_id, occurred_at), KEY inventory_movement_lot (lot_id), KEY inventory_movement_source (source_type, source_id), CONSTRAINT inventory_movement_lot_fk FOREIGN KEY (lot_id) REFERENCES inventory_lot(id), CONSTRAINT inventory_movement_item_fk FOREIGN KEY (item_id) REFERENCES inventory_item(id), CONSTRAINT inventory_movement_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_receipt_history (id CHAR(36) PRIMARY KEY, receipt_id CHAR(36) NOT NULL, action VARCHAR(16) NOT NULL, actor_person_id CHAR(36) NOT NULL, reason VARCHAR(1000) NULL, created_at DATETIME(6) NOT NULL, KEY inventory_receipt_history_receipt (receipt_id, created_at), CONSTRAINT inventory_receipt_history_receipt_fk FOREIGN KEY (receipt_id) REFERENCES inventory_receipt(id), CONSTRAINT inventory_receipt_history_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_sequence (kind VARCHAR(8) NOT NULL, buddhist_year INT NOT NULL, last_value INT NOT NULL, PRIMARY KEY (kind, buddhist_year)) DEFAULT CHARSET=utf8mb4
